<section class="panel"><header class="panel-head"><div><span class="eyebrow">Supplier invoice register</span><h2>Invoices and line evidence</h2></div><span class="panel-meta"><?= count($invoices) ?> invoice(s)</span></header><?php if(can('purchase_orders.create')): ?><form class="compact-form" action="<?= h(app_url('fulfillment-action.php')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save_invoice"><input type="hidden" name="purchase_order_id" value="<?= (int)$selected['id'] ?>"><input type="hidden" name="id" value="<?= (int)($invoice['id']??0) ?>"><label><span>Invoice number</span><input name="invoice_number" required value="<?= h($invoice['invoice_number']??'') ?>"></label><label><span>Invoice / due dates</span><span><input type="date" name="invoice_date" value="<?= h($invoice['invoice_date']??date('Y-m-d')) ?>"><input type="date" name="due_date" value="<?= h($invoice['due_date']??date('Y-m-d',strtotime('+30 days'))) ?>"></span></label><label><span>Subtotal</span><input type="number" min="0" step="0.01" name="subtotal" value="<?= h((string)($invoice['subtotal']??0)) ?>"></label><label><span>Freight</span><input type="number" min="0" step="0.01" name="freight_amount" value="<?= h((string)($invoice['freight_amount']??0)) ?>"></label><label><span>Tax</span><input type="number" min="0" step="0.01" name="tax_amount" value="<?= h((string)($invoice['tax_amount']??0)) ?>"></label><label><span>Payment terms</span><input name="payment_terms" value="<?= h($invoice['payment_terms']??(data_find('suppliers',$selected['supplier_id'])['payment_terms']??'Net 30')) ?>"></label><label><span>Owner / reviewer</span><span><select name="owner_id"><?= user_options($invoice['owner_id']??$selected['owner_id']) ?></select><select name="reviewer_id"><?= user_options($invoice['reviewer_id']??$selected['reviewer_id']) ?></select></span></label><label><span>Document reference</span><input name="document_path" value="<?= h($invoice['document_path']??'') ?>"></label><div class="span-2 inline-actions"><button class="button primary" type="submit">Save Invoice Header</button></div></form><?php endif; ?><?php if($invoice&&can('purchase_orders.create')): ?><form class="compact-form" action="<?= h(app_url('fulfillment-action.php')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save_invoice_line"><input type="hidden" name="invoice_id" value="<?= (int)$invoice['id'] ?>"><label><span>Purchase-order line</span><select name="purchase_order_line_id"><?php foreach($poLines as $line): ?><option value="<?= (int)$line['id'] ?>"><?= h($line['description'].' · '.money($line['unit_cost'])) ?></option><?php endforeach; ?></select></label><label><span>Description</span><input name="description" value="<?= h($poLines[0]['description']??'') ?>"></label><label><span>Quantity invoiced</span><input type="number" min="0.0001" step="0.0001" name="quantity_invoiced" required></label><label><span>Unit price</span><input type="number" min="0.0001" step="0.0001" name="unit_price" value="<?= h((string)($poLines[0]['unit_cost']??0)) ?>" required></label><div class="span-2 inline-actions"><button class="button secondary" type="submit">Add Invoice Line</button></div></form><?php endif; ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Invoice</th><th>Status</th><th>Dates</th><th class="numeric">Amount</th><th>Match / payment</th></tr></thead><tbody><?php foreach($invoices as $candidate): $candidateMatch=fulfillment_matches((int)$candidate['id'])[0]??null; ?><tr><td><a href="<?= h(app_url('fulfillment.php?id='.(int)$selected['id'].'&invoice_id='.(int)$candidate['id'])) ?>"><strong><?= h($candidate['invoice_number']) ?></strong></a><small><?= h($candidate['payment_terms']) ?></small></td><td><?= badge(fulfillment_invoice_effective_status($candidate)) ?></td><td><?= h(date_us($candidate['invoice_date'])) ?><small>Due <?= h(date_us($candidate['due_date'])) ?></small></td><td class="numeric"><strong><?= money($candidate['total_amount']) ?></strong></td><td><?= $candidateMatch?badge($candidateMatch['match_status']):badge('not_matched') ?><small><?= $candidateMatch?'Score '.number_format((float)$candidateMatch['match_score'],1):'Add lines and run match' ?></small></td></tr><?php endforeach; ?><?php if(!$invoices): ?><tr><td colspan="5"><?php render_empty_state('No supplier invoices','Create an invoice header and line evidence to begin three-way matching.'); ?></td></tr><?php endif; ?></tbody></table></div></section>
